// Auftrag prüfen: Jedes Eingangs-Item ist ein Auftrag an die Dateiablage. Alle Items eines Aufrufs haben dieselbe Aktion.
// Eingang je Item: aktion (ablegen, holen, pruefen, liste, verschieben, loeschen), bereich (ally oder buchhaltung, Standard ally),
// pfad (relativ zum Bereich), bei verschieben ziel_pfad und optional ziel_bereich, bei ablegen Binärfeld "datei" oder Text in "text",
// optional ueberschreiben (Standard: ja). Wo die Dateien liegen, steht in der Datenbank (ablage_ziel): Server oder eigener Speicherort per WebDAV.
const SERVER = '/files';
const AKTIONEN = ['ablegen', 'holen', 'pruefen', 'liste', 'verschieben', 'loeschen'];
const Z = $('Ziel laden').first().json.z || {};
const art = Z.art === 'webdav' ? 'webdav' : 'server';
const bereiche = Z.bereiche || {};
const s = v => String(v ?? '').trim();
const q = v => "'" + String(v).replace(/'/g, "'\\''") + "'";
const enc = p => p.split('/').filter(Boolean).map(encodeURIComponent).join('/');
const adresse = s(Z.adresse).replace(/\/+$/, '');
// Pfad prüfen: relativ, keine leeren oder Punkt-Teile, keine Steuerzeichen und keine Platzhalterzeichen
const pfadFehler = p => {
  if (!p) return 'Kein Pfad angegeben.';
  if (p.length > 1000) return 'Der Pfad ist zu lang.';
  if (p.startsWith('/') || p.includes('\\')) return 'Der Pfad muss relativ sein.';
  if (/[\u0000-\u001f\u007f*?{}]/.test(p)) return 'Der Pfad enthält unzulässige Zeichen.';
  const teile = p.split('/');
  if (teile.some(t => t === '' || t === '.' || t === '..' || t.length > 255)) return 'Der Pfad ist ungültig.';
  return '';
};
const wurzel = b => {
  const e = bereiche[b];
  if (!e) return { fehler: 'Unbekannter Bereich: ' + b };
  if (art === 'server') return { server: SERVER + '/' + s(e.server).replace(/^\/+|\/+$/g, '') };
  if (!s(e.extern)) return { fehler: 'Für den Bereich ' + b + ' ist beim eigenen Speicherort kein Ordner eingerichtet.' };
  return { extern: '/' + s(e.extern).replace(/^\/+|\/+$/g, '') };
};
const eingang = $('Start').all();
const aktion0 = s(eingang[0] && eingang[0].json.aktion);
const raus = [];
const fehler = (nr, j, text) => raus.push({ json: { weg: 'fehler', nr, aktion: s(j.aktion), bereich: s(j.bereich) || 'ally', pfad: s(j.pfad), fehler: text } });
// Aufträge vorbereiten
const auftraege = [];
for (let nr = 0; nr < eingang.length; nr++) {
  const it = eingang[nr], j = it.json || {};
  const aktion = s(j.aktion), bereich = s(j.bereich) || 'ally', pfad = s(j.pfad).replace(/^\.\//, '');
  if (!AKTIONEN.includes(aktion)) { fehler(nr, j, 'Unbekannte Aktion: ' + aktion); continue; }
  if (aktion !== aktion0) { fehler(nr, j, 'Alle Aufträge eines Aufrufs brauchen dieselbe Aktion.'); continue; }
  const pf = pfadFehler(pfad); if (pf) { fehler(nr, j, pf); continue; }
  const w = wurzel(bereich); if (w.fehler) { fehler(nr, j, w.fehler); continue; }
  const a = { nr, aktion, bereich, pfad, w, ueberschreiben: j.ueberschreiben !== false && s(j.ueberschreiben) !== 'nein' };
  if (aktion === 'verschieben') {
    a.ziel_bereich = s(j.ziel_bereich) || bereich; a.ziel_pfad = s(j.ziel_pfad);
    const zf = pfadFehler(a.ziel_pfad); if (zf) { fehler(nr, j, 'Ziel: ' + zf); continue; }
    a.zw = wurzel(a.ziel_bereich); if (a.zw.fehler) { fehler(nr, j, a.zw.fehler); continue; }
  }
  if (aktion === 'ablegen') {
    const bin = it.binary && (it.binary.datei || it.binary.data);
    if (bin) a.binary = bin;
    else if (typeof j.text === 'string') a.binary = await this.helpers.prepareBinaryData(Buffer.from(j.text, 'utf8'), pfad.split('/').pop(), 'text/plain; charset=utf-8');
    else { fehler(nr, j, 'Keine Datei zum Ablegen übergeben.'); continue; }
  }
  auftraege.push(a);
}
if (raus.length) return raus.concat(auftraege.map(a => ({ json: { weg: 'fehler', nr: a.nr, aktion: a.aktion, bereich: a.bereich, pfad: a.pfad, fehler: 'Nicht ausgeführt, weil ein anderer Auftrag dieses Aufrufs ungültig ist.' } })));
if (!auftraege.length) return [{ json: { weg: 'fehler', nr: 0, aktion: aktion0, fehler: 'Kein Auftrag übergeben.' } }];

if (art === 'server') {
  const voll = (w, p) => w.server + '/' + p;
  if (aktion0 === 'holen') return auftraege.map(a => ({ json: { weg: 'server_holen', nr: a.nr, aktion: a.aktion, bereich: a.bereich, pfad: a.pfad, datei_pfad: voll(a.w, a.pfad), befehl: 'p=' + q(voll(a.w, a.pfad)) + '; if [ -f "$p" ]; then echo OK; else echo FEHLT; fi' } }));
  if (aktion0 === 'ablegen') return auftraege.map(a => {
    const d = voll(a.w, a.pfad);
    const befehl = 'p=' + q(d) + '; ' + (a.ueberschreiben ? '' : 'if [ -e "$p" ]; then echo ZIEL_VORHANDEN; exit 0; fi; ') + 'mkdir -p -- "$(dirname -- "$p")" && echo OK';
    return { json: { weg: 'server_schreiben', nr: a.nr, aktion: a.aktion, bereich: a.bereich, pfad: a.pfad, datei_pfad: d, befehl }, binary: { datei: a.binary } };
  });
  return auftraege.map(a => {
    const d = voll(a.w, a.pfad);
    let befehl;
    if (a.aktion === 'pruefen') befehl = 'p=' + q(d) + '; if [ -f "$p" ]; then echo "DATEI $(stat -c %s -- "$p")"; elif [ -d "$p" ]; then echo ORDNER; else echo FEHLT; fi';
    else if (a.aktion === 'liste') befehl = 'd=' + q(d) + '; if [ ! -d "$d" ]; then echo FEHLT; exit 0; fi; echo ORDNER; cd -- "$d" && for f in *; do [ -e "$f" ] || continue; if [ -d "$f" ]; then printf \'d\\t0\\t%s\\n\' "$f"; else printf \'f\\t%s\\t%s\\n\' "$(stat -c %s -- "$f")" "$f"; fi; done';
    else if (a.aktion === 'loeschen') befehl = 'p=' + q(d) + '; if [ -e "$p" ] || [ -L "$p" ]; then rm -rf -- "$p" && echo OK; else echo FEHLT; fi';
    else befehl = 'p=' + q(d) + '; z=' + q(voll(a.zw, a.ziel_pfad)) + '; if [ ! -e "$p" ]; then echo QUELLE_FEHLT; exit 0; fi; ' + (a.ueberschreiben ? 'if [ -d "$z" ]; then echo ZIEL_VORHANDEN; exit 0; fi; ' : 'if [ -e "$z" ]; then echo ZIEL_VORHANDEN; exit 0; fi; ') + 'mkdir -p -- "$(dirname -- "$z")" && mv -f -- "$p" "$z" && echo OK';
    return { json: { weg: 'server_befehl', nr: a.nr, aktion: a.aktion, bereich: a.bereich, pfad: a.pfad, ziel_bereich: a.ziel_bereich, ziel_pfad: a.ziel_pfad, befehl } };
  });
}

// Eigener Speicherort per WebDAV: ein Plan-Item; die folgenden Schritte legen zuerst fehlende Ordner von oben nach unten an,
// dann führen sie die Aufträge aus. Dateien hängen am Plan-Item als d0, d1, ...
if (!/^https?:\/\/[^\/\s]+$/.test(adresse)) return auftraege.map(a => ({ json: { weg: 'fehler', nr: a.nr, aktion: a.aktion, bereich: a.bereich, pfad: a.pfad, fehler: 'Für den eigenen Speicherort ist keine gültige Adresse eingerichtet.' } }));
const url = (w, p) => adresse + '/' + enc(w.extern) + (p ? '/' + enc(p) : '');
const ordner = [];
const ordnerAnlegen = (w, p) => {
  const teile = p.split('/'); teile.pop();
  for (let i = 1; i <= teile.length; i++) { const u = url(w, teile.slice(0, i).join('/')) + '/'; if (!ordner.includes(u)) ordner.push(u); }
};
const plan = { aktion: aktion0, wurzel: url(auftraege[0].w, '') + '/', ordner, auftraege: [] };
const binaer = {};
for (const a of auftraege) {
  if (aktion0 === 'ablegen') ordnerAnlegen(a.w, a.pfad);
  if (aktion0 === 'verschieben') ordnerAnlegen(a.zw, a.ziel_pfad);
  const e = { nr: a.nr, aktion: a.aktion, bereich: a.bereich, pfad: a.pfad, url: url(a.w, a.pfad), ueberschreiben: a.ueberschreiben };
  if (a.aktion === 'verschieben') Object.assign(e, { ziel_bereich: a.ziel_bereich, ziel_pfad: a.ziel_pfad, ziel_url: url(a.zw, a.ziel_pfad) });
  if (a.aktion === 'ablegen') binaer['d' + a.nr] = a.binary;
  plan.auftraege.push(e);
}
return [{ json: { weg: 'webdav', plan }, binary: binaer }];

// Ergebnis: je Auftrag ein Item mit ok, aktion, bereich, pfad und je nach Aktion bytes, vorhanden, ordner, eintraege oder der Datei (Binärfeld "datei").
// Fehlertexte sind für Menschen geschrieben und können so an Ally oder die Oberfläche gehen.
const Z = $('Ziel laden').first().json.z || {};
const ort = Z.art === 'webdav' ? (Z.name || 'eigener Speicherort') : 'Server';
const A = $('Auftrag prüfen').all();
const weg = A.length ? A[0].json.weg : 'fehler';
const R = $input.all();
const n = v => (v === undefined || v === null || v === '' ? null : Number(v));
const kopf = (h, k) => { h = h || {}; const f = Object.keys(h).find(x => x.toLowerCase() === k); return f ? h[f] : undefined; };
const aus = (a, extra) => Object.assign({ ok: true, aktion: a.aktion, bereich: a.bereich, pfad: a.pfad, ort }, a.ziel_pfad ? { ziel_bereich: a.ziel_bereich, ziel_pfad: a.ziel_pfad } : {}, extra);
const fehl = (a, text) => aus(a, { ok: false, fehler: text });
const stdout = r => String((r && r.json && r.json.stdout) || '').trim();
const stderr = r => String((r && r.json && (r.json.stderr || (r.json.error && (r.json.error.message || r.json.error)))) || '').trim().slice(0, 300);
let raus = [];

if (weg === 'fehler') {
  raus = A.map(a => ({ json: fehl(a.json, a.json.fehler) }));
} else if (weg === 'server_befehl') {
  raus = A.map((a, i) => {
    const j = a.json, r = R[i], o = stdout(r), code = Number(r && r.json && r.json.exitCode);
    if (j.aktion === 'pruefen') {
      if (o.startsWith('DATEI ')) return { json: aus(j, { vorhanden: true, ordner: false, datei: true, bytes: Number(o.slice(6)) }) };
      if (o === 'ORDNER') return { json: aus(j, { vorhanden: true, ordner: true }) };
      if (o === 'FEHLT') return { json: aus(j, { vorhanden: false }) };
    } else if (j.aktion === 'liste') {
      if (o === 'FEHLT') return { json: aus(j, { vorhanden: false, eintraege: [] }) };
      if (o.startsWith('ORDNER') && code === 0) {
        const eintraege = o.split('\n').slice(1).filter(Boolean).map(z => { const t = z.split('\t'); return { name: t.slice(2).join('\t'), ordner: t[0] === 'd', bytes: t[0] === 'd' ? null : Number(t[1]) }; });
        return { json: aus(j, { vorhanden: true, eintraege }) };
      }
    } else if (j.aktion === 'loeschen') {
      if (o === 'OK') return { json: aus(j, { vorhanden: true }) };
      if (o === 'FEHLT') return { json: aus(j, { vorhanden: false }) };
    } else if (j.aktion === 'verschieben') {
      if (o === 'OK' && code === 0) return { json: aus(j, {}) };
      if (o === 'QUELLE_FEHLT') return { json: fehl(j, 'Die Datei ' + j.pfad + ' gibt es nicht.') };
      if (o === 'ZIEL_VORHANDEN') return { json: fehl(j, 'Am Ziel ' + j.ziel_pfad + ' liegt schon etwas.') };
    }
    return { json: fehl(j, 'Speichern auf dem Server fehlgeschlagen (' + (stderr(r) || o || 'keine Antwort') + ').') };
  });
} else if (weg === 'server_holen') {
  const V = $('Server: Vorprüfen').all();
  raus = A.map((a, i) => {
    const r = R[i];
    if (stdout(V[i]) !== 'OK') return { json: fehl(a.json, 'Die Datei ' + a.json.pfad + ' gibt es nicht.') };
    if (r && r.binary && r.binary.datei && !(r.json && r.json.error)) return { json: aus(a.json, {}), binary: { datei: r.binary.datei } };
    return { json: fehl(a.json, 'Die Datei ' + a.json.pfad + ' konnte nicht gelesen werden.') };
  });
} else if (weg === 'server_schreiben') {
  const R1 = $('Server: Ordner anlegen').all();
  raus = A.map((a, i) => {
    const j = a.json, o1 = stdout(R1[i]), o3 = stdout(R[i]);
    if (o1 === 'ZIEL_VORHANDEN') return { json: fehl(j, 'Die Datei ' + j.pfad + ' gibt es schon und wurde nicht überschrieben.') };
    if (!/OK$/.test(o1)) return { json: fehl(j, 'Der Ordner für ' + j.pfad + ' konnte nicht angelegt werden (' + (stderr(R1[i]) || o1 || 'keine Antwort') + ').') };
    if (o3.startsWith('DATEI ')) return { json: aus(j, { bytes: Number(o3.slice(6)) }) };
    return { json: fehl(j, 'Die Datei ' + j.pfad + ' ist auf dem Server nicht angekommen.') };
  });
} else {
  // Eigener Speicherort (WebDAV): Antworten je Schritt in derselben Reihenfolge wie die Aufträge
  const plan = A[0].json.plan;
  const st = r => Number(r && r.json && r.json.statusCode);
  const ordnerFehler = $('Eigener Speicherort: Ordner anlegen').all().map(st).filter(c => ![200, 201, 207, 405].includes(c)).map(c => c || 'keine Antwort');
  const statusText = c => c === 401 || c === 403 ? 'keine Berechtigung' : c === 423 ? 'Datei ist gesperrt' : c === 507 ? 'Speicher voll' : c ? 'Status ' + c : 'keine Antwort';
  const xmlListe = txt => {
    // N9 (Migration 123, vorbereitet als 109): Ordner ist, was irgendwo eine collection nennt (jedes Präfix, mit/ohne Attribute, mit/ohne Endtag);
    // typ nur, wenn ein resourcetype in einem propstat mit Status 200 steht. Im Zweifel ist das Ziel keine sichere Datei.
    const bloecke = String(txt || '').split(/<(?:[\w-]+:)?response[\s>]/).slice(1);
    return bloecke.map(b => {
      const href = decodeURIComponent(((b.match(/<(?:[\w-]+:)?href>([^<]*)</) || [])[1] || '').replace(/\/+$/, ''));
      const ordner = /<\s*(?:[\w.-]+:)?collection(?=[\s\/>])/i.test(b);
      const ok200 = b.split(/<(?:[\w.-]+:)?propstat[\s>]/i).slice(1).filter(p => /<(?:[\w.-]+:)?status>\s*HTTP\/[\d.]+\s+200(?!\d)/i.test(p));
      const typ = ok200.some(p => /<\s*(?:[\w.-]+:)?resourcetype(?=[\s\/>])/i.test(p));
      const laenge = (b.match(/<(?:[\w-]+:)?getcontentlength>(\d+)</) || [])[1];
      return { href, name: href.split('/').pop(), ordner, typ, bytes: ordner ? null : n(laenge) };
    });
  };
  const S = plan.aktion === 'ablegen' ? $('Eigener Speicherort: Senden').all() : R;
  const G = plan.aktion === 'ablegen' ? $('Größe bestimmen').all() : [];
  raus = plan.auftraege.map((j, i) => {
    const r = S[i], c = st(r);
    if (j.aktion === 'ablegen') {
      const h = R[i], hs = st(h);
      if (c === 412) return { json: fehl(j, 'Die Datei ' + j.pfad + ' gibt es schon und wurde nicht überschrieben.') };
      if (c === 423) return { json: aus(j, { ok: false, gesperrt: true, fehler: 'Die Datei ' + j.pfad + ' ist gerade geöffnet und konnte nicht überschrieben werden. Bitte schließen und nochmal anfordern.' }) };
      if (![200, 201, 204].includes(c)) return { json: fehl(j, 'Speichern auf ' + ort + ' fehlgeschlagen (' + statusText(c) + (ordnerFehler.length ? ', Ordner anlegen: ' + ordnerFehler.join(', ') : '') + ').') };
      const laenge = n(kopf(h && h.json && h.json.headers, 'content-length'));
      const soll = n(G[i] && G[i].json.bytes);
      if (hs !== 200 || soll === null || laenge !== soll) return { json: fehl(j, 'Die Datei ' + j.pfad + ' ist auf ' + ort + ' nicht vollständig angekommen' + (hs === 200 ? ' (' + laenge + ' statt ' + soll + ' Bytes)' : '') + '.') };
      return { json: aus(j, { bytes: laenge }) };
    }
    if (j.aktion === 'holen') {
      if (c === 200 && r.binary && r.binary.datei) return { json: aus(j, {}), binary: { datei: r.binary.datei } };
      return { json: fehl(j, c === 404 ? 'Die Datei ' + j.pfad + ' gibt es nicht.' : 'Die Datei ' + j.pfad + ' konnte nicht geholt werden (' + statusText(c) + ').') };
    }
    if (j.aktion === 'pruefen') {
      if (c === 404) return { json: aus(j, { vorhanden: false }) };
      if (c === 207) { const e = xmlListe(r.json.data)[0] || {}; return { json: aus(j, Object.assign({ vorhanden: true, ordner: !!e.ordner }, e.ordner ? {} : { bytes: e.bytes, typ_bekannt: e.typ === true })) }; }
      return { json: fehl(j, 'Prüfen fehlgeschlagen (' + statusText(c) + ').') };
    }
    if (j.aktion === 'liste') {
      if (c === 404) return { json: aus(j, { vorhanden: false, eintraege: [] }) };
      if (c === 207) return { json: aus(j, { vorhanden: true, eintraege: xmlListe(r.json.data).slice(1).map(x => ({ name: x.name, ordner: x.ordner, bytes: x.bytes })) }) };
      return { json: fehl(j, 'Auflisten fehlgeschlagen (' + statusText(c) + ').') };
    }
    if (j.aktion === 'loeschen') {
      if ([200, 204].includes(c)) return { json: aus(j, { vorhanden: true }) };
      if (c === 404) return { json: aus(j, { vorhanden: false }) };
      return { json: fehl(j, 'Löschen fehlgeschlagen (' + statusText(c) + ').') };
    }
    if ([201, 204].includes(c)) return { json: aus(j, {}) };
    if (c === 404) return { json: fehl(j, 'Die Datei ' + j.pfad + ' gibt es nicht.') };
    if (c === 412) return { json: fehl(j, 'Am Ziel ' + j.ziel_pfad + ' liegt schon etwas.') };
    return { json: fehl(j, 'Verschieben fehlgeschlagen (' + statusText(c) + (ordnerFehler.length ? ', Ordner anlegen: ' + ordnerFehler.join(', ') : '') + ').') };
  });
}
return raus.length ? raus : [{ json: { ok: false, fehler: 'Kein Ergebnis.' } }];

// Datei anhängen: Nach dem Anlegen der Ordner bekommt jedes Item seine Datei zurück.
// Wurde ein Auftrag abgelehnt (Ziel vorhanden, Fehler), zeigt der Pfad bewusst auf einen nicht beschreibbaren Ort; der Schreibschritt meldet dann nur einen Fehler, den "Ergebnis" ignoriert.
const A = $('Auftrag prüfen').all();
return $input.all().map((r, i) => {
  const a = A[i];
  const ok = Number(r.json.exitCode) === 0 && /OK\s*$/.test(String(r.json.stdout || ''));
  return { json: { nr: a.json.nr, ok, datei_pfad: ok ? a.json.datei_pfad : '/dev/null/abgelehnt' }, binary: { datei: a.binary.datei } };
});

// Lesbare auswählen: Nur vorhandene Dateien lesen. Fehlt eine Datei, zeigt der Pfad bewusst auf einen nicht lesbaren Ort;
// der Leseschritt meldet dann einen Fehler und die Zahl der Items bleibt gleich, damit "Ergebnis" die Aufträge zuordnen kann.
const A = $('Auftrag prüfen').all();
return $input.all().map((r, i) => {
  const ok = String(r.json.stdout || '').trim() === 'OK';
  return { json: { nr: A[i].json.nr, ok, datei_pfad: ok ? A[i].json.datei_pfad : '/dev/null/fehlt' } };
});

// Ordner-Anfragen: fehlende Ordner von oben nach unten anlegen (vorhandene melden 405). Ohne neue Ordner nur eine Leseprüfung
// des Bereichs, damit die folgenden Schritte immer laufen und ein nicht erreichbarer Speicherort früh auffällt.
const plan = $('Auftrag prüfen').first().json.plan;
const liste = plan.ordner.map(u => ({ json: { schritt: 'ordner', methode: 'MKCOL', url: u, kopf: {} } }));
return liste.length ? liste : [{ json: { schritt: 'ordner', methode: 'PROPFIND', url: plan.wurzel, kopf: { Depth: '0' } } }];

// Schritte: je Auftrag eine Anfrage an den eigenen Speicherort (gleiche Reihenfolge wie die Aufträge)
const P = $('Auftrag prüfen').first();
const plan = P.json.plan;
return plan.auftraege.map(a => {
  const b = { nr: a.nr, url: a.url, kopf: {} };
  if (a.aktion === 'ablegen') return { json: Object.assign(b, { art: 'senden', methode: 'PUT', kopf: a.ueberschreiben ? {} : { 'If-None-Match': '*' } }), binary: { datei: P.binary['d' + a.nr] } };
  if (a.aktion === 'holen') return { json: Object.assign(b, { art: 'holen', methode: 'GET' }) };
  if (a.aktion === 'pruefen') return { json: Object.assign(b, { art: 'anfrage', methode: 'PROPFIND', kopf: { Depth: '0' } }) };
  if (a.aktion === 'liste') return { json: Object.assign(b, { art: 'anfrage', methode: 'PROPFIND', url: a.url + '/', kopf: { Depth: '1' } }) };
  if (a.aktion === 'loeschen') return { json: Object.assign(b, { art: 'anfrage', methode: 'DELETE' }) };
  return { json: Object.assign(b, { art: 'anfrage', methode: 'MOVE', kopf: { Destination: a.ziel_url, Overwrite: a.ueberschreiben ? 'T' : 'F' } }) };
});

// Nachprüf-Anfragen: nach dem Senden jede Datei einmal abfragen, um die Größe zu vergleichen.
// Accept-Encoding identity: sonst meldet der Speicher bei Textdateien die gepackte Größe.
return $('Eigener Speicherort: Schritte').all().map(s => ({ json: { nr: s.json.nr, methode: 'HEAD', url: s.json.url, kopf: { 'Accept-Encoding': 'identity' } } }));

// Größe bestimmen: genaue Größe jeder Datei vor dem Senden, damit "Ergebnis" sie mit der Größe auf dem Speicherort vergleichen kann
const raus = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'datei');
  raus.push({ json: Object.assign({}, items[i].json, { bytes: buf.length }), binary: items[i].binary });
}
return raus;

// Ordner: Plan (SPEICHER 1, Migration 67): Ordner im eigenen Speicherort – auflisten, anlegen, umbenennen (Personen mit Recht am Speicherort) und für Talents
